using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Covers the wire contract with the payment provider: what <see cref="HttpPaymentGateway"/>
/// sends on the request and how it interprets every answer the provider can give back.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_the_request_body()
    {
        var handler = new StubHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var gateway = CreateGateway(handler);

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.NotNull(handler.LastRequest);
        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.PathAndQuery);

        using var payload = JsonDocument.Parse(handler.LastRequestBody!);
        var root = payload.RootElement;
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(42.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_reported_as_approved()
    {
        var handler = new StubHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_reported_as_declined()
    {
        var handler = new StubHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"declined"}"""));
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_in_the_body_is_treated_as_declined()
    {
        var handler = new StubHandler(_ => JsonResponse(HttpStatusCode.OK, """{"status":"pending"}"""));
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_empty_body_is_treated_as_declined()
    {
        var handler = new StubHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("null", Encoding.UTF8, "application/json"),
        });
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_from_the_provider_is_reported_as_declined_without_reading_the_body()
    {
        var handler = new StubHandler(_ => new HttpResponseMessage(HttpStatusCode.PaymentRequired));
        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_error_status_from_the_provider_throws()
    {
        var handler = new StubHandler(_ => new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var gateway = CreateGateway(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpPaymentGateway CreateGateway(StubHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example.test") };
        return new HttpPaymentGateway(client);
    }

    private static HttpResponseMessage JsonResponse(HttpStatusCode status, string json)
        => new(status) { Content = new StringContent(json, Encoding.UTF8, "application/json") };

    private sealed class StubHandler(Func<HttpRequestMessage, HttpResponseMessage> respond) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }

        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null
                ? null
                : await request.Content.ReadAsStringAsync(cancellationToken);

            return respond(request);
        }
    }
}
